-- SLA-617: experiment completion webhook.
--   Experiment.notifyJson  the caller's notify config ({url, secret, metadata}); a
--                          column, not dataJson, so the secret never rides serialize().
--   ExperimentWebhookOutbox  one row per non-terminal -> terminal transition,
--                          inserted in the same batch as the status UPDATE and
--                          delivered by the VPS worker with backoff.
--
-- Mirrors prisma/schema.prisma (and prisma/schema.sqlite.prisma, generated by
-- src/scripts/sync-sqlite-schema.ts).
--
-- Apply with: wrangler d1 migrations apply slashloop --remote
ALTER TABLE "Experiment" ADD COLUMN "notifyJson" TEXT;
CREATE TABLE IF NOT EXISTS "ExperimentWebhookOutbox" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "experimentId" TEXT NOT NULL,
  "workspaceId" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  "idempotencyKey" TEXT NOT NULL,
  "notifyJson" TEXT NOT NULL,
  "payloadJson" TEXT NOT NULL,
  "state" TEXT NOT NULL DEFAULT 'pending',
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "nextAttemptAt" DATETIME NOT NULL,
  "lastError" TEXT,
  "deliveredAt" DATETIME,
  "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "ExperimentWebhookOutbox_idempotencyKey_key" ON "ExperimentWebhookOutbox"("idempotencyKey");
CREATE INDEX IF NOT EXISTS "ExperimentWebhookOutbox_state_nextAttemptAt_idx" ON "ExperimentWebhookOutbox"("state", "nextAttemptAt");
